List<int> parseNestedParens(String parenString) {
  if (parenString.isEmpty || !parenString.contains('(')) return [];

  final stack = <int>[]; // Holds depths of all opening parentheses
  int depth = 0;         // Current nesting level

  for (var i = 0; i < parenString.length; i++) {
    char c = parenString[i];

    if (c == '(') {
      depth++;
      stack.add(depth);

      if (stack.length > 1 && 
          stack.last - stack[stack.length - 2] != 1 &&
          !(i + 1 < parenString.length && parenString[i+1] == ')')) {
        return [depth];
      }

    } else if (c == ')') {
      depth--;
      stack.removeLast();

      if (stack.isNotEmpty) {
        int lastDepth = stack.last;

        // Check adjacent groupings at the same level
        bool foundAdjacent = false;
        while (lastDepth >= stack.length) {
          if (stack.isEmpty) break;

          if (lastDepth - stack.last == 1) {
            foundAdjacent = true;
            break;
          } else {
            lastDepth = stack.last;
          }
        }

        if (!foundAdjacent) {
          return [stack.last];
        }
      }
    }
  }

  if (stack.isNotEmpty) return [stack.last];
  return [];
