  int len = s.length;
  List<String> chars = s.split('');

  // Create a list of indices to shuffle: [0,1,...,n-1]
  List<int> order = List.generate(len, (i) => i);

  // Randomly reorder the indices multiple times until we get one that's not the identity.
  while (true) {
    for (int i = 0; i < len * 2; ++i) {
      int r = rand.nextInt(len);
      int t = order[r];
      order[r] = order[i % len];
      order[i % len] = t;
    }

    bool isIdentity = true;
    for (int i = 0; i < len; ++i) {
      if (order[i] != i) {
        isIdentity = false; break;
      }
    }

    if (!isIdentity) break;
  }

  // Rebuild string using shuffled index order
  List<char> result = List.filled(len, '\u{FFFE}');
  for (int i = 0; i < len; ++i) {
    result[order[i]] = chars[i];
  }

  String res = String.fromCharCodes(result.map((c) => c.codeUnitAt(0)));
  return res.replaceAll('\u{FFFE}', '');
}

String antiShuffle(String s) {
