  int n = s.length;
  List<String> chars = s.split('');

  List<int> order = [];
  for (int i = 0; i < n; i++) {
    order.add(i);
  }

  Random random = new Random();
  while (order.length > 1) {
    int last = order.last;

    double p = (n - order.length).toDouble() / n.toDouble();
    bool keepLast = random.nextDouble() >= p;

    if (!keepLast && order.isNotEmpty) {
      int indexToMove = random.nextInt(order.length);
      String item = order.removeAt(indexToMove);

      // Find position to insert based on original indices
      int pos = 0;
      for (int j = 0; j < order.length; j++) {
        if (chars[order[j]] == item) {
          break;
        }
        pos++;
      }

      order.insert(pos, item);
    } else {
      order.removeAt(last);
    }
  }

  final resultChars = [''];
  for (final char in chars) {
    if (char != '') {
      resultChars.add(char);
    }
  }

  StringBuffer sb = StringBuffer();
  for (var c in chars) {
    if (c == ' ') {
      continue;
    }
    sb.write(c);
  }

  String textPart = sb.toString();
  String spacePositions = '';

  int currentSpaceCount = 0;
  for (int i = 0; i < n; i++) {
    if (i > 0 && chars[i] == ' ') {
      currentSpaceCount += 2 * (currentSpaceCount + 1);
    }
  }

  while (textPart.contains(' ')) {
    int spaceIndex = textPart.indexOf(' ');
    if (spaceIndex == -1) break;

    String leftPart = textPart.substring(0, spaceIndex);
    String rightPart = textPart.substring(spaceIndex + 1);

    int totalSpacesBefore = currentSpaceCount ~/ 2;
    int spacesInLeft = leftPart.split('').where((e) => e == ' ').length;
    int remainingSpacesAfter = totalSpacesBefore - spacesInLeft;

    int targetInsertionPoint = remainingSpacesAfter ~/ 2;
    targetInsertionPoint = min(targetInsertionPoint, max(0, rightPart.length));

    String processedRight = rightPart.substring(0, targetInsertionPoint) + 
                           ' ' * remainingSpacesAfter + 
                           rightPart.substring(targetInsertionPoint);

    textPart = '$leftPart$processedRight';
  }

  List<String> words = textPart.trim().split(' ', 50);
  Collections.shuffle(words, () => random.nextDouble());

  List<String> sortedWords = words.toList();
  Collections.sort(sortedWords, (a, b) => a.compareTo(b));

  List<String> shuffledResult = sortedWords.reversed.toList();
  shuffle(shuffledResult, () => random.nextLong());

  StringBuffer outputBuffer = StringBuffer();
  for (var word in shuffledResult) {
    outputBuffer.writeln(word);
  }

  return outputBuffer.toString().trimAll();
}

