  // Query type A: find minimum subarray sum of length k starting at index l
  void queryA(int l, int r, int k) {
    String key = '$l,$r,$k';
    if (!queries.containsKey(key)) queries[key] = [];

    double mid = (l + r).toDouble() / 2.0;
    double leftBound = mid * k.toDouble();
    double rightBound = (mid + 0.5) * k.toDouble();
    double leftIndex = floor(leftBound);
    double rightIndex = ceil(rightBound);

    if (leftIndex >= k && rightIndex <= prefix[n]) {
      var bestMin = double.infinity;
