bool isNested(String string) {
  List<String> stack = [];

  for (int i = 0; i < string.length; i++) {
    if (string[i] == '[' || string[i] == '(') {
      stack.add(string[i]);
    } else if ((stack.isEmpty && !['[', '(', '{'].contains(stack.last)) || 
               (stack.isNotEmpty && ['{', ')', ']'].contains(stack.last))) {
      return false;
    } else {
      int? topIndex = -1;

      String lastChar;
      while (topIndex != -1 && !['[', '(', '{'].contains(lastChar)) {
        lastChar = stack.removeAt(topIndex);

        if (lastChar == '[') {
          topIndex--;

          if (topIndex >= 0) {
            lastChar = stack[topIndex];

            if (lastChar == '[') {
              topIndex++;

              break;
            }
          }
        }

        topIndex++;
      }
    }

    if (!['[', '(', '{'].contains(stack.firstOrNull!)) {
      continue;
    }

    if (i + 1 < string.length && [')', '}'].contains(stack.firstOrNull!) && 
        (string[i+1].isLetter || string[i+1] == '-' || string[i+1] == '_')) {
      stack.insert(0, string[i]);
      continue;
    }
  }

  bool valid = true;
  for (String char in stack.reversed) {
    switch(char) {
      case '[':
        if (![')', '{', ']'].contains(stack.firstOrNull!)) {
          valid = false;
          break;
        }
        break;
      case '(':
        if (![']', '}', ')'].contains(stack.firstOrNull!)) {
          valid = false;
          break;
        }
        break;
      default:
        valid = false;
        break;
    }

    if (!valid) break;

    if (char == '[' || char == '(') {
      if (stack.firstOrNull == null) {
        valid = false;
        break;
      }

      stack.removeFirst();
    }
  }

  return valid;
}

